import { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Box,
  Card,
  CardContent,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  TextField,
  MenuItem,
  IconButton,
  Tooltip,
  Button,
  Typography,
  Stack,
  Avatar,
  Divider,
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import FilterAltOutlinedIcon from '@mui/icons-material/FilterAltOutlined';
import VisibilityOutlinedIcon from '@mui/icons-material/VisibilityOutlined';
import EditOutlinedIcon from '@mui/icons-material/EditOutlined';
import CheckCircleOutlinedIcon from '@mui/icons-material/CheckCircleOutlined';
import PendingActionsOutlinedIcon from '@mui/icons-material/PendingActionsOutlined';
import ErrorOutlineOutlinedIcon from '@mui/icons-material/ErrorOutlineOutlined';
import InboxOutlinedIcon from '@mui/icons-material/InboxOutlined';
import AssignmentTurnedInOutlinedIcon from '@mui/icons-material/AssignmentTurnedInOutlined';
import PageHeader from '../../components/common/PageHeader';
import AppBreadcrumbs from '../../components/common/AppBreadcrumbs';
import StatusChip from '../../components/common/StatusChip';
import ConfirmDialog from '../../components/common/ConfirmDialog';
import reviewService from '../../api/reviewService';
import { COUNTRIES, countryName } from '../../utils/countries';
import { REVIEW_STATUSES, REVIEW_STATUS_LABELS } from '../../utils/reviewEnums';

const SUMMARY_CARD_CONFIG = [
  { key: 'total', label: 'Total Reviews', icon: AssignmentTurnedInOutlinedIcon, color: 'primary' },
  { key: 'PENDING', label: 'Pending', icon: PendingActionsOutlinedIcon, color: 'warning' },
  { key: 'APPROVED', label: 'Approved', icon: CheckCircleOutlinedIcon, color: 'success' },
  { key: 'REJECTED', label: 'Rejected', icon: ErrorOutlineOutlinedIcon, color: 'error' },
];

export default function ReviewListPage() {
  const navigate = useNavigate();
  const [reviews, setReviews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [country, setCountry] = useState('');
  const [status, setStatus] = useState('');
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(5);
  const [pendingAction, setPendingAction] = useState(null);
  const [actionType, setActionType] = useState('');

  const fetchReviews = () =>
    reviewService.list().then((data) => {
      setReviews(data);
      setLoading(false);
    });

  useEffect(() => {
    fetchReviews();
  }, []);

  const filtered = useMemo(() => {
    let result = reviews;
    if (country) result = result.filter((review) => review.countryCode === country);
    if (status) result = result.filter((review) => review.status === status);
    if (search.trim()) {
      const query = search.trim().toLowerCase();
      result = result.filter(
        (review) =>
          review.title.toLowerCase().includes(query) ||
          review.reviewer.toLowerCase().includes(query) ||
          countryName(review.countryCode).toLowerCase().includes(query)
      );
    }
    return result;
  }, [reviews, search, country, status]);

  const filterKey = `${search}|${country}|${status}`;
  const [lastFilterKey, setLastFilterKey] = useState(filterKey);
  if (filterKey !== lastFilterKey) {
    setLastFilterKey(filterKey);
    setPage(0);
  }

  const summaryCounts = useMemo(
    () => ({
      total: reviews.length,
      PENDING: reviews.filter((review) => review.status === 'PENDING').length,
      APPROVED: reviews.filter((review) => review.status === 'APPROVED').length,
      REJECTED: reviews.filter((review) => review.status === 'REJECTED').length,
    }),
    [reviews]
  );

  const paged = useMemo(
    () => filtered.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage),
    [filtered, page, rowsPerPage]
  );

  const hasActiveFilters = Boolean(search.trim() || country || status);

  const clearFilters = () => {
    setSearch('');
    setCountry('');
    setStatus('');
  };

  const handleConfirmAction = () => {
    if (!pendingAction) return;
    const actionMap = {
      approve: () => reviewService.approve(pendingAction.id),
      reject: () => reviewService.reject(pendingAction.id),
      requestChanges: () => reviewService.requestChanges(pendingAction.id),
      publish: () => reviewService.publish(pendingAction.id),
    };

    actionMap[actionType]().then(() => {
      setPendingAction(null);
      setActionType('');
      fetchReviews();
    });
  };

  return (
    <Box>
      <AppBreadcrumbs items={[{ label: 'Dashboard', href: '/' }, { label: 'Review Workflow' }]} />

      <PageHeader
        title="Review & Approval Workflow"
        subtitle="Track review requests, manage approvals, and publish accepted content."
        actions={
          <Button variant="contained" startIcon={<AddIcon />} onClick={() => navigate('/reviews/new')}>
            New Review
          </Button>
        }
      />

      <Box
        sx={{
          display: 'grid',
          gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr', md: 'repeat(4, 1fr)' },
          gap: 2,
          mb: 3,
        }}
      >
        {SUMMARY_CARD_CONFIG.map(({ key, label, icon: Icon, color }) => (
          <Card key={key} variant="outlined">
            <CardContent>
              <Stack direction="row" spacing={2} alignItems="center">
                <Avatar sx={{ bgcolor: `${color}.main`, width: 40, height: 40 }}>
                  <Icon fontSize="small" />
                </Avatar>
                <Box>
                  <Typography variant="h6" fontWeight={700}>
                    {summaryCounts[key]}
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    {label}
                  </Typography>
                </Box>
              </Stack>
            </CardContent>
          </Card>
        ))}
      </Box>

      <Paper variant="outlined" sx={{ p: 2.5, mb: 3 }}>
        <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 2 }}>
          <FilterAltOutlinedIcon fontSize="small" color="action" />
          <Typography variant="subtitle2" color="text.secondary">
            Search &amp; Filter
          </Typography>
        </Stack>
        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
          <TextField
            label="Search"
            placeholder="Search by title, reviewer, or country"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            fullWidth
            size="small"
          />
          <TextField select label="Country" value={country} onChange={(e) => setCountry(e.target.value)} size="small" sx={{ minWidth: 180 }}>
            <MenuItem value="">All Countries</MenuItem>
            {COUNTRIES.map((countryOption) => (
              <MenuItem key={countryOption.code} value={countryOption.code}>
                {countryOption.name}
              </MenuItem>
            ))}
          </TextField>
          <TextField select label="Status" value={status} onChange={(e) => setStatus(e.target.value)} size="small" sx={{ minWidth: 180 }}>
            <MenuItem value="">All Statuses</MenuItem>
            {REVIEW_STATUSES.map((reviewStatus) => (
              <MenuItem key={reviewStatus} value={reviewStatus}>
                {REVIEW_STATUS_LABELS[reviewStatus]}
              </MenuItem>
            ))}
          </TextField>
          {hasActiveFilters && (
            <Button onClick={clearFilters} sx={{ whiteSpace: 'nowrap' }}>
              Clear Filters
            </Button>
          )}
        </Stack>
      </Paper>

      <TableContainer component={Paper} variant="outlined" sx={{ overflowX: 'auto' }}>
        <Table sx={{ minWidth: 760 }}>
          <TableHead>
            <TableRow>
              <TableCell>Title</TableCell>
              <TableCell>Country</TableCell>
              <TableCell>Reviewer</TableCell>
              <TableCell>Status</TableCell>
              <TableCell align="right">Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {!loading && filtered.length === 0 && (
              <TableRow>
                <TableCell colSpan={5}>
                  <Stack alignItems="center" spacing={1} sx={{ py: 5 }}>
                    <InboxOutlinedIcon fontSize="large" color="disabled" />
                    <Typography variant="body1" color="text.secondary">
                      {reviews.length === 0 ? 'No review requests yet.' : 'No review requests match your filters.'}
                    </Typography>
                    {reviews.length === 0 ? (
                      <Button variant="contained" size="small" onClick={() => navigate('/reviews/new')}>
                        Create your first review
                      </Button>
                    ) : (
                      <Button size="small" onClick={clearFilters}>
                        Clear filters
                      </Button>
                    )}
                  </Stack>
                </TableCell>
              </TableRow>
            )}
            {paged.map((review) => (
              <TableRow key={review.id} hover>
                <TableCell>
                  <Typography variant="body2" fontWeight={600}>
                    {review.title}
                  </Typography>
                </TableCell>
                <TableCell>{countryName(review.countryCode)}</TableCell>
                <TableCell>{review.reviewer}</TableCell>
                <TableCell>
                  <StatusChip status={review.status} />
                </TableCell>
                <TableCell align="right">
                  <Stack direction="row" spacing={0.5} justifyContent="flex-end">
                    <Tooltip title="View">
                      <IconButton size="small" onClick={() => navigate(`/reviews/${review.id}`)}>
                        <VisibilityOutlinedIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                    <Tooltip title="Edit">
                      <IconButton size="small" onClick={() => navigate(`/reviews/${review.id}/edit`)}>
                        <EditOutlinedIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                    <Tooltip title="Approve">
                      <IconButton size="small" color="success" onClick={() => { setPendingAction(review); setActionType('approve'); }}>
                        <CheckCircleOutlinedIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                    <Tooltip title="Reject">
                      <IconButton size="small" color="error" onClick={() => { setPendingAction(review); setActionType('reject'); }}>
                        <ErrorOutlineOutlinedIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                    <Tooltip title="Request Changes">
                      <IconButton size="small" color="warning" onClick={() => { setPendingAction(review); setActionType('requestChanges'); }}>
                        <PendingActionsOutlinedIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                    <Tooltip title="Publish">
                      <IconButton size="small" color="primary" onClick={() => { setPendingAction(review); setActionType('publish'); }}>
                        <AssignmentTurnedInOutlinedIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                  </Stack>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
        {filtered.length > 0 && (
          <>
            <Divider />
            <TablePagination
              component="div"
              count={filtered.length}
              page={page}
              onPageChange={(_e, newPage) => setPage(newPage)}
              rowsPerPage={rowsPerPage}
              onRowsPerPageChange={(e) => {
                setRowsPerPage(parseInt(e.target.value, 10));
                setPage(0);
              }}
              rowsPerPageOptions={[5, 10, 25]}
            />
          </>
        )}
      </TableContainer>

      <ConfirmDialog
        open={Boolean(pendingAction)}
        title={actionType === 'approve' ? 'Approve this review?' : actionType === 'reject' ? 'Reject this review?' : actionType === 'requestChanges' ? 'Request changes?' : 'Publish this review?'}
        message={pendingAction ? `"${pendingAction.title}" will be moved to the selected workflow state.` : ''}
        confirmLabel={actionType === 'approve' ? 'Approve' : actionType === 'reject' ? 'Reject' : actionType === 'requestChanges' ? 'Request Changes' : 'Publish'}
        confirmColor={actionType === 'reject' ? 'error' : actionType === 'requestChanges' ? 'warning' : 'primary'}
        onConfirm={handleConfirmAction}
        onCancel={() => { setPendingAction(null); setActionType(''); }}
      />
    </Box>
  );
}

