import { Formik, Form } from 'formik';
import { Box, TextField, MenuItem, Button, Stack, Paper, Typography, Divider } from '@mui/material';
import { reviewValidationSchema } from '../../utils/reviewValidation';
import { COUNTRIES } from '../../utils/countries';
import { REVIEW_STATUSES, REVIEW_STATUS_LABELS } from '../../utils/reviewEnums';

const gridSx = {
  display: 'grid',
  gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr' },
  gap: 2,
};

function FormSection({ title, description, children }) {
  return (
    <Paper variant="outlined" sx={{ p: 3, mb: 3 }}>
      <Typography variant="subtitle1" fontWeight={600}>
        {title}
      </Typography>
      {description && (
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          {description}
        </Typography>
      )}
      <Divider sx={{ mb: 2.5, mt: description ? 0 : 1.5 }} />
      <Box sx={gridSx}>{children}</Box>
    </Paper>
  );
}

export default function ReviewForm({ initialValues, onSubmit, onCancel, submitLabel = 'Save' }) {
  return (
    <Formik
      initialValues={initialValues}
      validationSchema={reviewValidationSchema}
      enableReinitialize
      onSubmit={onSubmit}
    >
      {({ values, errors, touched, handleChange, handleBlur, isSubmitting }) => (
        <Form noValidate>
          <FormSection title="Review Details" description="Capture the review request and the expected sign-off status.">
            <TextField
              label="Title"
              name="title"
              value={values.title}
              onChange={handleChange}
              onBlur={handleBlur}
              error={touched.title && Boolean(errors.title)}
              helperText={touched.title && errors.title}
              fullWidth
            />

            <TextField
              select
              label="Country"
              name="countryCode"
              value={values.countryCode}
              onChange={handleChange}
              onBlur={handleBlur}
              fullWidth
            >
              <MenuItem value="">Select a country</MenuItem>
              {COUNTRIES.map((country) => (
                <MenuItem key={country.code} value={country.code}>
                  {country.name}
                </MenuItem>
              ))}
            </TextField>

            <TextField
              label="Reviewer"
              name="reviewer"
              value={values.reviewer}
              onChange={handleChange}
              onBlur={handleBlur}
              error={touched.reviewer && Boolean(errors.reviewer)}
              helperText={touched.reviewer && errors.reviewer}
              fullWidth
            />

            <TextField
              select
              label="Status"
              name="status"
              value={values.status}
              onChange={handleChange}
              onBlur={handleBlur}
              error={touched.status && Boolean(errors.status)}
              helperText={touched.status && errors.status}
              fullWidth
            >
              {REVIEW_STATUSES.map((status) => (
                <MenuItem key={status} value={status}>
                  {REVIEW_STATUS_LABELS[status]}
                </MenuItem>
              ))}
            </TextField>

            <TextField
              label="Comments"
              name="comments"
              value={values.comments}
              onChange={handleChange}
              onBlur={handleBlur}
              error={touched.comments && Boolean(errors.comments)}
              helperText={touched.comments && errors.comments}
              multiline
              minRows={4}
              fullWidth
              sx={{ gridColumn: { sm: '1 / span 2' } }}
            />
          </FormSection>

          <Stack direction="row" spacing={2} justifyContent="flex-end">
            <Button onClick={onCancel} disabled={isSubmitting}>
              Cancel
            </Button>
            <Button type="submit" variant="contained" disabled={isSubmitting}>
              {submitLabel}
            </Button>
          </Stack>
        </Form>
      )}
    </Formik>
  );
}

