import { useEffect, useState } from 'react';
import { useNavigate, useParams, Link as RouterLink } from 'react-router-dom';
import { Box, Card, CardContent, Paper, Typography, Button, Stack, Avatar } from '@mui/material';
import EditOutlinedIcon from '@mui/icons-material/EditOutlined';
import CheckCircleOutlineOutlinedIcon from '@mui/icons-material/CheckCircleOutlineOutlined';
import CancelOutlinedIcon from '@mui/icons-material/CancelOutlined';
import PendingActionsOutlinedIcon from '@mui/icons-material/PendingActionsOutlined';
import PublishOutlinedIcon from '@mui/icons-material/PublishOutlined';
import PublicOutlinedIcon from '@mui/icons-material/PublicOutlined';
import PersonOutlinedIcon from '@mui/icons-material/PersonOutlined';
import ScheduleOutlinedIcon from '@mui/icons-material/ScheduleOutlined';
import PageHeader from '../../components/common/PageHeader';
import AppBreadcrumbs from '../../components/common/AppBreadcrumbs';
import StatusChip from '../../components/common/StatusChip';
import ConfirmDialog from '../../components/common/ConfirmDialog';
import reviewService from '../../api/reviewService';
import { countryName } from '../../utils/countries';

function InfoCard({ label, value, icon: Icon }) {
  return (
    <Card variant="outlined">
      <CardContent>
        <Stack direction="row" spacing={2} alignItems="center">
          <Avatar sx={{ bgcolor: 'primary.main', width: 40, height: 40 }}>
            <Icon fontSize="small" />
          </Avatar>
          <Box>
            <Typography variant="subtitle1" fontWeight={700}>
              {value}
            </Typography>
            <Typography variant="caption" color="text.secondary">
              {label}
            </Typography>
          </Box>
        </Stack>
      </CardContent>
    </Card>
  );
}

function Section({ title, children }) {
  return (
    <Paper variant="outlined" sx={{ p: 3, mb: 3 }}>
      <Typography variant="subtitle1" fontWeight={600} sx={{ mb: 1.5 }}>
        {title}
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ whiteSpace: 'pre-wrap' }}>
        {children || 'Not provided.'}
      </Typography>
    </Paper>
  );
}

export default function ReviewDetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [review, setReview] = useState(undefined);
  const [confirmAction, setConfirmAction] = useState(null);

  const load = () => {
    reviewService.getById(id).then(setReview);
  };

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  if (review === undefined) {
    return <Typography>Loading…</Typography>;
  }

  if (review === null) {
    return (
      <Box>
        <AppBreadcrumbs items={[{ label: 'Dashboard', href: '/' }, { label: 'Review Workflow', href: '/reviews' }, { label: 'Not Found' }]} />
        <Typography variant="h6" sx={{ mb: 2 }}>
          Review request not found.
        </Typography>
        <Button component={RouterLink} to="/reviews" variant="contained">
          Back to Reviews
        </Button>
      </Box>
    );
  }

  const handleAction = () => {
    if (!confirmAction) return;

    const actionMap = {
      approve: reviewService.approve(review.id),
      reject: reviewService.reject(review.id),
      requestChanges: reviewService.requestChanges(review.id),
      publish: reviewService.publish(review.id),
    };

    actionMap[confirmAction].then(() => {
      setConfirmAction(null);
      load();
    });
  };

  const actionLabel = confirmAction === 'approve' ? 'Approve' : confirmAction === 'reject' ? 'Reject' : confirmAction === 'requestChanges' ? 'Request Changes' : 'Publish';

  return (
    <Box>
      <AppBreadcrumbs items={[{ label: 'Dashboard', href: '/' }, { label: 'Review Workflow', href: '/reviews' }, { label: review.title }]} />

      <PageHeader
        title={review.title}
        subtitle={review.reviewer}
        actions={
          <Stack direction="row" spacing={1}>
            <Button variant="outlined" startIcon={<EditOutlinedIcon />} onClick={() => navigate(`/reviews/${review.id}/edit`)}>
              Edit
            </Button>
            <Button variant="outlined" color="success" startIcon={<CheckCircleOutlineOutlinedIcon />} onClick={() => setConfirmAction('approve')}>
              Approve
            </Button>
            <Button variant="outlined" color="error" startIcon={<CancelOutlinedIcon />} onClick={() => setConfirmAction('reject')}>
              Reject
            </Button>
            <Button variant="outlined" color="warning" startIcon={<PendingActionsOutlinedIcon />} onClick={() => setConfirmAction('requestChanges')}>
              Request Changes
            </Button>
            <Button variant="outlined" color="primary" startIcon={<PublishOutlinedIcon />} onClick={() => setConfirmAction('publish')}>
              Publish
            </Button>
          </Stack>
        }
      />

      <Stack direction="row" spacing={1} sx={{ mb: 3 }}>
        <StatusChip status={review.status} />
      </Stack>

      <Box
        sx={{
          display: 'grid',
          gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr', md: 'repeat(3, 1fr)' },
          gap: 2,
          mb: 3,
        }}
      >
        <InfoCard label="Country" value={countryName(review.countryCode)} icon={PublicOutlinedIcon} />
        <InfoCard label="Reviewer" value={review.reviewer} icon={PersonOutlinedIcon} />
        <InfoCard label="Created" value={new Date(review.createdAt).toLocaleString()} icon={ScheduleOutlinedIcon} />
      </Box>

      <Section title="Comments">{review.comments}</Section>
      <Paper variant="outlined" sx={{ p: 3 }}>
        <Typography variant="subtitle1" fontWeight={600} sx={{ mb: 1.5 }}>
          Review Notes
        </Typography>
        <Typography variant="body2" color="text.secondary">
          Updated {review.updatedAt ? new Date(review.updatedAt).toLocaleString() : '—'}
        </Typography>
      </Paper>

      <ConfirmDialog
        open={Boolean(confirmAction)}
        title={`${actionLabel} this review?`}
        message={`"${review.title}" will move to the ${actionLabel.toLowerCase()} workflow state.`}
        confirmLabel={actionLabel}
        confirmColor={confirmAction === 'reject' ? 'error' : confirmAction === 'requestChanges' ? 'warning' : 'primary'}
        onConfirm={handleAction}
        onCancel={() => setConfirmAction(null)}
      />
    </Box>
  );
}

