import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Box, Typography } from '@mui/material';
import PageHeader from '../../components/common/PageHeader';
import AppBreadcrumbs from '../../components/common/AppBreadcrumbs';
import ReviewForm from './ReviewForm';
import reviewService from '../../api/reviewService';
import { emptyReview } from '../../utils/reviewValidation';

export default function ReviewEditPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [initialValues, setInitialValues] = useState(null);
  const [notFound, setNotFound] = useState(false);

  useEffect(() => {
    reviewService.getById(id).then((review) => {
      if (!review) {
        setNotFound(true);
        return;
      }
      setInitialValues({ ...emptyReview, ...review });
    });
  }, [id]);

  const handleSubmit = (values, { setSubmitting }) => {
    reviewService.update(id, values).then((review) => {
      setSubmitting(false);
      navigate(`/reviews/${review.id}`);
    });
  };

  if (notFound) {
    return <Typography>Review request not found.</Typography>;
  }

  if (!initialValues) {
    return <Typography>Loading…</Typography>;
  }

  return (
    <Box>
      <AppBreadcrumbs items={[{ label: 'Dashboard', href: '/' }, { label: 'Reviews', href: '/reviews' }, { label: 'Edit Review' }]} />
      <PageHeader title="Edit Review Request" subtitle="Update the review request details and approval status." />
      <ReviewForm
        initialValues={initialValues}
        onSubmit={handleSubmit}
        onCancel={() => navigate(`/reviews/${id}`)}
        submitLabel="Save Changes"
      />
    </Box>
  );
}

